140→// AssertHasShadowBranches asserts that at least one shadow branch (entire/*)
141→// exists, excluding entire/checkpoints/*. Use this when the shadow branch is
142→// expected to persist (e.g., session is still idle).
143→func AssertHasShadowBranches(t *testing.T, dir string) {
144→	t.Helper()
145→	shadow := shadowBranches(t, dir)
146→	assert.NotEmpty(t, shadow,
147→		"expected at least one shadow branch to persist, but none found")
148→}
