181→// AssertCheckpointInLastN asserts the given checkpoint ID appears in at
182→// least n commits on the checkpoint branch (e.g. initial + catchup).
183→// Uses --grep to find matching commits regardless of position, so extra
184→// commits from multi-commit agent turns don't cause false failures.
185→func AssertCheckpointInLastN(t *testing.T, dir string, checkpointID string, n int) {
186→	t.Helper()
187→	out := GitOutput(t, dir, "log", "--grep="+checkpointID,
188→		"--format=%s", "entire/checkpoints/v1")
189→	var lines []string
190→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
191→		if line != "" {
192→			lines = append(lines, line)
193→		}
194→	}
195→	assert.GreaterOrEqual(t, len(lines), n,
196→		"expected at least %d commits mentioning %s on checkpoint branch, got %d: %v",
197→		n, checkpointID, len(lines), lines)
198→}
