277→// WaitForSessionIdle polls the session state files in .git/entire-sessions/
278→// until no session has phase "active", or fails the test after timeout.
279→// This handles the race where an agent's prompt pattern appears in the TUI
280→// before the turn-end hook has completed (transitioning ACTIVE → IDLE).
281→func WaitForSessionIdle(t *testing.T, dir string, timeout time.Duration) {
282→	t.Helper()
283→	stateDir := filepath.Join(dir, ".git", "entire-sessions")
284→	deadline := time.Now().Add(timeout)
285→	for time.Now().Before(deadline) {
286→		entries, err := os.ReadDir(stateDir)
287→		if err != nil {
288→			// Directory may not exist yet; keep polling
289→			time.Sleep(200 * time.Millisecond)
290→			continue
291→		}
292→		anyActive := false
293→		for _, entry := range entries {
294→			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") || strings.HasSuffix(entry.Name(), ".tmp") {
295→				continue
296→			}
297→			data, err := os.ReadFile(filepath.Join(stateDir, entry.Name()))
298→			if err != nil {
299→				continue
300→			}
301→			var state struct {
302→				Phase string `json:"phase"`
303→			}
304→			if err := json.Unmarshal(data, &state); err != nil {
305→				continue
306→			}
307→			if state.Phase == "active" {
308→				anyActive = true
309→				break
310→			}
311→		}
312→		if !anyActive {
313→			return
314→		}
315→		time.Sleep(200 * time.Millisecond)
316→	}
317→	t.Fatalf("session(s) did not transition to idle within %s", timeout)
318→}
